from pathlib import Path
import hashlib, json, re
root = Path('products/distribution/sqlite-community-directory')
readme = root / 'raw/awesome-sqlite-readme.md'
patch = root / 'raw/merged-pr-42.patch.txt'
headings = []
for line in readme.read_text().splitlines():
    if re.match(r'^#{1,6} ', line):
        headings.append(line)
readme_diff = False
changes = []
for line in patch.read_text().splitlines():
    if line.startswith('diff --git '):
        readme_diff = bool(re.fullmatch(r'diff --git a/README\.md b/README\.md', line, re.I))
    elif readme_diff and (line.startswith('@@ ') or re.match(r'^[+-]\s*(?:[-*]\s+\[|#{1,6} )', line)):
        changes.append(line)
result = {'patch_url': 'https://patch-diff.githubusercontent.com/raw/planetopendata/awesome-sqlite/pull/42.patch', 'patch_sha256': hashlib.sha256(patch.read_bytes()).hexdigest(), 'readme_sha256': hashlib.sha256(readme.read_bytes()).hexdigest(), 'current_headings': headings, 'readme_listing_and_heading_diff': changes, 'scope': 'One patch. An addition here can inform placement. Its absence leaves placement to the current README. Neither result establishes contribution eligibility, traffic or demand.'}
output = root / 'pr42-placement-evidence.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
print(output.read_text())
